organizer_public_attribution_receipts_re.value:
(
        "organizer_public_attribution_receipts"."action" IN ('adopted', 'confirmed')
      ) OR (
        "organizer_public_attribution_receipts"."action" = 'revoked'
        AND "organizer_public_attribution_receipts"."related_receipt_id" IS NOT NULL
      )

public_form_rate_windows_count_check.value:
(
        "public_form_rate_windows"."action" = 'public_form_scope_15m'
        AND "public_form_rate_windows"."request_count" BETWEEN 1 AND 5
      ) OR (
        "public_form_rate_windows"."action" = 'public_form_scope_day'
        AND "public_form_rate_windows"."request_count" BETWEEN 1 AND 20
      ) OR (
        "public_form_rate_windows"."action" = 'public_form_organization_hour'
        AND "public_form_rate_windows"."request_count" BETWEEN 1 AND 500
      )

public_slug_redirects_state_shape_check.value:
(
        "public_slug_redirects"."state" = 'active' AND "public_slug_redirects"."retired_at" IS NULL
      ) OR (
        "public_slug_redirects"."state" = 'superseded'
        AND "public_slug_redirects"."retired_at" IS NOT NULL
      )
